    public static double[] lerp(double t, double[] low, double[] high) {
        return new double[] {
            low[0] + t * (high[0] - low[0]),
            low[1] + t * (high[1] - low[1])
        };
    }

    public static double[] getValues(double distance) {
        double k_step = 0.1;
        double maxDistance = 198.0;
        int n = points.length;

        if (Double.isNaN(distance) || n == 0 || k_step <= 0.0) {
            return new double[] { Double.NaN, Double.NaN };
        }

        // ---- Clamp out-of-bounds ----
        if (distance <= 0.0) {
            return points[0];
        }
        if (distance >= maxDistance) {
            return points[n - 1];
        }

        // ---- Interpolate ----
        int low = (int) Math.floor(distance / k_step);
        int high = low + 1;

        double t = (distance - low * k_step) / k_step;
        return lerp(t, points[low], points[high]);
    }

    private Aimbot() {}
